{
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "applicability_explanation": null,
        "statement": "The purpose of 8 FAM 801.2 is to provide guidance regarding the use of information request letters (IRLs) and information notices (INs).",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "applicability_explanation": "Identifies the definition of information request letters (IRLs) in 8 FAM 801.2-1(b).",
        "statement": "Information request letters (IRLs) are personalized, standardized letters with a date and signature block that request from the applicant additional information, documentation, or action needed to process the passport application.",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "applicability_explanation": "Identifies the adjudicator's duty before suspending an application in 8 FAM 801.2-1(b).",
        "statement": "You must fully adjudicate the application prior to suspending to ensure that you are addressing all issues.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "applicability_explanation": "Descriptive background regarding the design of IRLs in 8 FAM 801.2-1(b).",
        "statement": "The IRLs have been carefully crafted to communicate clearly and accurately statutory, regulatory, and other requirements of the Department.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "applicability_explanation": "Governs passport agencies/centers regarding alterations to IRLs under 8 FAM 801.2-1(b)(1), including approval requirements and the extenuating circumstances exception.",
        "statement": "Passport agencies/centers must not make unilateral changes or alterations to the IRLs without the approval of the Office of Adjudication (CA/PPT/S/A), except on a case-by-case basis with the approval of passport agency/center management in extenuating circumstances (e.g., when you request that the applicant submit a birth certificate instead of a notification of birth registration, and the applicant insists that the notification of birth registration is the birth certificate).",
        "kind": "prohibition",
        "modality": "must_not",
        "modality_quote": "must not"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "applicability_explanation": "Specifies the baseline duty for posts using IRLs under 8 FAM 801.2-1(b)(2).",
        "statement": "Posts must use the cleared language in the IRLs.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "applicability_explanation": "Specifies authority granted to posts to modify IRL language under 8 FAM 801.2-1(b)(2).",
        "statement": "Posts are authorized to modify the language in the IRLs to suit local logistical requirements and other local concerns such as available documentation.",
        "kind": "authority",
        "modality": "may"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "applicability_explanation": "Clarifies the non-adjudicative status of IRLs in the Note following 8 FAM 801.2-1(b)(2).",
        "statement": "IRLs are not adjudicative guidance.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "applicability_explanation": "Sets forth the requirement for adjudicating passport applications and selecting IRLs in the Note to 8 FAM 801.2-1(b)(2).",
        "statement": "The passport application must be adjudicated in accordance with 8 FAM and then the appropriate IRL selected to address any deficiencies with the passport or Consular Report of Birth Abroad (CRBA).",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "references": [
          "8 FAM"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "applicability_explanation": "Provides the definition and general purpose of information notices (INs) under 8 FAM 801.2-1(c).",
        "statement": "Information notices (INs) are standardized notices that provide passport bearers with information about their passports.",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "applicability_explanation": "Describes illustrative examples of IN inclusion under 8 FAM 801.2-1(c).",
        "statement": "An IN may be included to explain why the passport was limited in validity, and/or what documentation is needed to obtain a fully valid passport.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "applicability_explanation": "Explains the design purpose of INs under 8 FAM 801.2-1(c).",
        "statement": "The INs have been carefully crafted to communicate this information clearly and accurately.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "applicability_explanation": "Prohibits unilateral changes to INs at passport agencies/centers, including the extenuating circumstances exception under 8 FAM 801.2-1(c).",
        "statement": "No changes or alterations to the INs may be made unilaterally at passport agencies/centers without the approval of CA/PPT/S/A, except in extenuating circumstances on a case-by-case basis with the approval of passport agency/center management (e.g., when using an endorsement 46 to limit a passport for a special problem).",
        "kind": "prohibition",
        "modality": "must_not",
        "modality_quote": "no changes or alterations to the INs may be made"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "applicability_explanation": "Specifies that INs do not require applicant response under 8 FAM 801.2-1(c).",
        "statement": "INs do not require a response from the applicant.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "do not require"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "applicability_explanation": "Specifies that INs do not require personalization under 8 FAM 801.2-1(c).",
        "statement": "INs do not need to be personalized with the applicant's name and address.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "do not need"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "applicability_explanation": "Identifies options available to posts when tailoring correspondence under 8 FAM 801.2-1(d).",
        "statement": "When tailoring correspondence to a situation, posts may consult Passport Services’ IRL index and IN Index or contact AskPPTAdjudication@state.gov.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    }
  ]
}
